import {
  execFileSync,
  execSync,
  spawn,
  type ChildProcess,
  type ExecFileSyncOptions,
  type SpawnOptions,
} from 'child_process';
import path from 'path';
import { errnoCode } from '../utils/errnoCode';
import { hostShell } from '../utils/hostShell';

const WINDOWS_SHELL_META_CHARACTER_PATTERN = /([()\][%!^"`<>&|;, *?])/g;
const processGroups = new WeakSet<ChildProcess>();

export type ProjectProcessCommand =
  { executable: string; args: string[] } | { shellCommand: string };

export type HostCommand = ProjectProcessCommand;

export type ProjectProcessService = {
  start: (
    command: ProjectProcessCommand,
    options: SpawnOptions,
  ) => ChildProcess;
  terminate: (
    process: ChildProcess,
    options: { isForceful: boolean; env?: NodeJS.ProcessEnv },
  ) => Promise<void>;
};

export type HostCommandService = {
  nativeExecutableName: (name: string) => string;
  executeSync: (
    command: HostCommand,
    options: Omit<ExecFileSyncOptions, 'shell'>,
  ) => string | Buffer;
};

export type OperatingSystemServices = {
  operatingSystemFamily: 'windows' | 'posix';
  hostCommands: HostCommandService;
  projectProcesses: ProjectProcessService;
};

export type OperatingSystemServiceDependencies = {
  spawn: typeof spawn;
  execFileSync?: typeof execFileSync;
  execSync?: typeof execSync;
  shell: string;
};

const defaultDependencies = (
  operatingSystem: NodeJS.Platform,
): OperatingSystemServiceDependencies => ({
  spawn,
  execFileSync,
  execSync,
  shell: hostShell(operatingSystem),
});

const escapeWindowsShellExecutable = (executable: string): string =>
  executable.replace(WINDOWS_SHELL_META_CHARACTER_PATTERN, '^$1');

const escapeWindowsShellArgument = (argument: string): string => {
  const escapedQuotes = argument.replace(/(?=(\\+?)?)\1"/g, '$1$1\\"');
  const escapedTrailingSlashes = escapedQuotes.replace(
    /(?=(\\+?)?)\1$/,
    '$1$1',
  );
  return `"${escapedTrailingSlashes}"`.replace(
    WINDOWS_SHELL_META_CHARACTER_PATTERN,
    '^$1',
  );
};

export const buildWindowsShellCommand = (command: HostCommand): string => {
  if ('shellCommand' in command) {
    return command.shellCommand;
  }
  return [
    escapeWindowsShellExecutable(command.executable),
    ...command.args.map(escapeWindowsShellArgument),
  ].join(' ');
};

export const buildWindowsBatchShimCommand = (command: {
  executable: string;
  args: string[];
}): string =>
  [
    escapeWindowsShellExecutable(command.executable),
    ...command.args.map((argument) =>
      escapeWindowsShellArgument(argument).replace(
        WINDOWS_SHELL_META_CHARACTER_PATTERN,
        '^$1',
      ),
    ),
  ].join(' ');

const terminateWindowsProcessTree = ({
  process,
  dependencies,
  env,
}: {
  process: ChildProcess;
  dependencies: OperatingSystemServiceDependencies;
  env?: NodeJS.ProcessEnv;
}): Promise<void> => {
  if (process.pid == null) {
    return Promise.resolve();
  }
  const args = ['/PID', String(process.pid), '/T', '/F'];
  return new Promise<void>((resolve, reject) => {
    const terminationProcess = dependencies.spawn('taskkill', args, {
      ...(env ? { env } : {}),
      stdio: 'ignore',
      windowsHide: true,
    });
    terminationProcess.once('error', reject);
    terminationProcess.once('close', (exitCode) => {
      if (exitCode === 0) {
        resolve();
        return;
      }
      reject(
        new Error(
          `taskkill failed for process ${process.pid} with exit code ${exitCode ?? 'unknown'}`,
        ),
      );
    });
  });
};

const createWindowsOperatingSystemServices = (
  dependencies: OperatingSystemServiceDependencies,
): OperatingSystemServices => ({
  operatingSystemFamily: 'windows',
  hostCommands: {
    nativeExecutableName: (name) => `${name}.exe`,
    executeSync: (command, options) => {
      if (
        'executable' in command &&
        path.win32.isAbsolute(command.executable)
      ) {
        return (dependencies.execFileSync ?? execFileSync)(
          command.executable,
          command.args,
          { ...options, windowsHide: true },
        );
      }
      return (dependencies.execSync ?? execSync)(
        buildWindowsShellCommand(command),
        {
          ...options,
          windowsHide: true,
        },
      );
    },
  },
  projectProcesses: {
    start: (command, options) => {
      if ('executable' in command && options.shell === false)
        return dependencies.spawn(command.executable, command.args, {
          ...options,
          windowsHide: true,
        });
      return dependencies.spawn(buildWindowsShellCommand(command), {
        ...options,
        shell: true,
        windowsHide: true,
      });
    },
    terminate: (process, { env }) =>
      terminateWindowsProcessTree({ process, dependencies, env }),
  },
});

const createPosixOperatingSystemServices = (
  dependencies: OperatingSystemServiceDependencies,
): OperatingSystemServices => ({
  operatingSystemFamily: 'posix',
  hostCommands: {
    nativeExecutableName: (name) => name,
    executeSync: (command, options) => {
      if ('executable' in command) {
        return (dependencies.execFileSync ?? execFileSync)(
          command.executable,
          command.args,
          options,
        );
      }
      return (dependencies.execSync ?? execSync)(command.shellCommand, {
        ...options,
        shell: dependencies.shell,
      });
    },
  },
  projectProcesses: {
    start: (command, options) => {
      const child =
        'executable' in command
          ? dependencies.spawn(command.executable, command.args, options)
          : dependencies.spawn(
              dependencies.shell,
              ['-l', '-c', command.shellCommand],
              options,
            );
      if (options.detached) processGroups.add(child);
      return child;
    },
    terminate: async (child, options) => {
      const signal = options.isForceful ? 'SIGKILL' : 'SIGTERM';
      if (processGroups.has(child) && child.pid) {
        try {
          process.kill(-child.pid, signal);
        } catch (error) {
          if (errnoCode(error) !== 'ESRCH') throw error;
          child.kill(signal);
        }
      } else {
        child.kill(signal);
      }
    },
  },
});

export const selectOperatingSystemServices = (
  operatingSystem: NodeJS.Platform,
  dependencies: OperatingSystemServiceDependencies = defaultDependencies(
    operatingSystem,
  ),
): OperatingSystemServices => {
  switch (operatingSystem) {
    case 'win32':
      return createWindowsOperatingSystemServices(dependencies);
    default:
      return createPosixOperatingSystemServices(dependencies);
  }
};

export const selectedOperatingSystemServices = selectOperatingSystemServices(
  process.platform,
);
